    /**
     * Handles loading a Report using a UUID
     * @param		UUID uuid 
     * @return		Report
     */    
    @GetMapping("/load")
    public Report load( @RequestParam(required=true) UUID uuid ) {    	
    	Report entity = null;

    	try {  
    		entity = service.getReport( new ReportFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Report using Id " + uuid );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Report business objects
     * @return		Set<Report>
     */
    @GetMapping("/")
    public List<Report> loadAll() {                
    	List<Report> reportList = null;
        
    	try {
            // load the Report
            reportList = service.getAllReport();
            
            if ( reportList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Reports" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Reports ", exc );
        	return null;
        }

        return reportList;
                            
    }

